import { createWriteStream } from 'fs';
import { pipeline } from 'stream/promises';
import { Readable } from 'stream';
import path from 'path';

/**
 * Generates a minimal PNG file (1x1 blue pixel)
 * This is sufficient for testing avatar upload functionality
 */
async function generateTestAvatar() {
  // Minimal PNG: 1x1 blue pixel
  const pngData = Buffer.from([
    0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a, // PNG signature
    0x00, 0x00, 0x00, 0x0d, 0x49, 0x48, 0x44, 0x52, // IHDR chunk
    0x00, 0x00, 0x00, 0x01, 0x00, 0x00, 0x00, 0x01, // 1x1 dimensions
    0x08, 0x02, 0x00, 0x00, 0x00, 0x90, 0x77, 0x53, // bit depth, color type, etc.
    0xde, 0x00, 0x00, 0x00, 0x0c, 0x49, 0x44, 0x41, // IDAT chunk
    0x54, 0x08, 0xd7, 0x63, 0x60, 0x00, 0x02, 0x00, // pixel data (blue)
    0x00, 0x05, 0x00, 0x01, 0xe2, 0x26, 0x05, 0x9b,
    0x00, 0x00, 0x00, 0x00, 0x49, 0x45, 0x4e, 0x44, // IEND chunk
    0xae, 0x42, 0x60, 0x82
  ]);

  const outputPath = path.join(process.cwd(), 'tests', 'fixtures', 'test-avatar.png');
  const writeStream = createWriteStream(outputPath);

  await pipeline(
    Readable.from(pngData),
    writeStream
  );

  console.log(`✅ Test avatar created at: ${outputPath}`);
}

generateTestAvatar().catch(console.error);
